sys_script.script:
// Validate last working date is not in the past (unless already set)
var lastWorkingDateStr = current.getValue('last_working_date');
if (lastWorkingDateStr && current.isNewRecord()) {
  var lastWorkingDate = new GlideDateTime();
  lastWorkingDate.setValue(lastWorkingDateStr);

  var today = new GlideDateTime();

  if (lastWorkingDate.compareTo(today) < 0) {
    gs.addErrorMessage('Last working date cannot be in the past');
    current.setAbortAction(true);
  }
}

// Validate employee email format
var email = current.getValue('employee_email');
if (email && !email.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
  gs.addErrorMessage('Invalid employee email format');
  current.setAbortAction(true);
}

// Ensure employee exists in sys_user table
if (current.getValue('employee')) {
  var userGr = new GlideRecord('sys_user');
  if (!userGr.get(current.getValue('employee'))) {
    gs.addErrorMessage('Employee record not found in system');
    current.setAbortAction(true);
  }
}
